<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_role(['customer']);$s=$pdo->prepare("SELECT * FROM bills WHERE customer_id=? ORDER BY created_at DESC");$s->execute([current_user()['customer_id']]);$rows=$s->fetchAll();$pageTitle='My bills';require 'includes/header.php';?>
<div class="panel"><h3>My water bills</h3><div class="table-wrap"><table><thead><tr><th>Bill number</th><th>Period</th><th>Consumption</th><th>Rate</th><th>Total</th><th>Balance</th><th>Due date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['bill_number'])?></td><td><?=e($r['billing_period'])?></td><td><?=number_format($r['consumption'],2)?> m³</td><td><?=money($r['rate_per_m3'])?></td><td><?=money($r['total_amount'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['due_date'])?></td><td><span class="pill <?=$r['balance']<=0?'success':'warning'?>"><?=$r['balance']<=0?'Paid':'Pending'?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No bills available.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
